const lessons = [
 {id:0,stage:0,title:'电力与电量：先把单位弄清',desc:'理解 MW、MWh 和时段长度，避免计算中的千倍误差。',minutes:8,sections:[['功率是一瞬间的速率','MW 描述发电或用电功率；MWh 描述一个时间段内的电能。1 MWh = 1,000 kWh。电费计算必须让电量单位与电价单位匹配。'],['从功率到电量','功率保持不变时，电量 = 功率 × 时间。80 MW 连续运行 15 分钟，产生 80 × 0.25 = 20 MWh。若功率随时间变化，要把各时段电量相加。'],['算一笔电费','20 MWh 按 350 元/MWh 计价，电能量费用为 7,000 元。此处不含输配电费、线损、政府性基金及其他费用。']],quiz:{q:'80 MW 运行 15 分钟的电量是？',options:['20 MWh','80 MWh','320 MWh'],answer:0,explain:'15 分钟 = 0.25 小时，80 × 0.25 = 20 MWh。'},lab:'energy'},
 {id:1,stage:0,title:'谁在市场里买卖电？',desc:'认识发电企业、用户、售电公司与市场运营机构。',minutes:10,sections:[['交易链条','发电企业生产电能；电力用户消费电能；售电公司为用户提供购电和零售服务。储能、虚拟电厂等新型经营主体按适用规则参与。'],['运营与输配电','电力交易机构、调度机构分别承担相应的交易组织与运行职责，具体分工以适用规则为准。电网提供输配电服务，不应将输配电服务与竞争性电能量交易混为一谈。'],['批发与零售','批发市场交易和售电公司对用户的零售合同属于不同层次。用户零售结算不一定等于批发现货价格乘以用电量，需要阅读零售合同。']],quiz:{q:'判断用户最终电费时，应同时关注什么？',options:['只看发电企业报价','零售合同与适用结算规则','只看某一天最高现货价'],answer:1,explain:'零售价格、费用项目及风险分配要依据合同和适用规则判断。'}},
 {id:2,stage:0,title:'一张图理解市场时间线',desc:'从年度合同，到日前计划，再到实时平衡。',minutes:10,sections:[['由远及近','中长期交易为未来期间安排电量与价格；日前市场在运行日前组织交易；实时市场处理临近运行的供需变化。不同市场安排的交割颗粒度与运行时序以当地规则为准。'],['为什么要实时平衡','电力系统需要持续保持供需平衡。负荷预测变化、新能源出力波动和机组故障都会使实际运行偏离计划。'],['价格与风险','中长期安排帮助管理价格风险，现货价格反映短期供需和系统约束。签订中长期合同不会让偏差或现货风险自动消失。']],quiz:{q:'实时市场主要应对哪类变化？',options:['公司年度招聘','临近运行的供需偏差','历史固定资产折旧'],answer:1,explain:'临近运行的供需变化需要实时调整。'}},
 {id:3,stage:1,title:'中长期合同怎样管理风险',desc:'理解合同电量、合同价格与差价结算。',minutes:12,sections:[['先区分合同类型','有的教学模型使用差价合约；实际中长期交易还涉及交割曲线、时段划分、合同调整及当地结算机制。不能把一个差价公式视为所有省份通用的完整规则。'],['差价模型','对于发电侧简化模型，收入 = 实发电量 × 现货价 + 合同电量 ×（合同价 − 现货价）。若实发电量恰好等于合同电量，收入等于合同电量乘以合同价。'],['偏差仍有价格风险','若合同为 80 MWh，实发 100 MWh，多出的 20 MWh 仍受到现货价格影响。签约比例越高也不必然越好，要结合出力和负荷预测。']],quiz:{q:'差价模型中，实际电量超过合同的部分主要受到什么影响？',options:['现货价格','合同签署人姓名','合同打印页数'],answer:0,explain:'未被合同覆盖的电量保留现货价格敞口。'},lab:'contract'},
 {id:4,stage:1,title:'报价如何形成出清价格',desc:'理解供给排序、边际机组与统一价格。',minutes:12,sections:[['供给排序','在忽略网络和机组复杂约束的单节点模型中，将报价从低到高排序，依次选取供给满足需求。最后一台需要调用的机组是边际机组。'],['统一边际价格','本教学模型采用统一边际价格，所有中标机组按边际机组报价结算。实际市场可能采用节点电价、分区电价及复杂优化模型。'],['模型边界','本算例没有考虑启停成本、最小出力、爬坡、输电约束、备用、需求价格弹性与限价。需求超过供给时，本模型报告缺额，不凭空设定出清价。']],quiz:{q:'统一边际价格的教学模型中，出清价由哪台机组决定？',options:['报价最高但未中标的机组','最后被调用的边际机组','报价最低的机组'],answer:1,explain:'供给按报价排序，满足需求所需的最后一台机组形成边际价格。'},lab:'clearing'},
 {id:5,stage:1,title:'辅助服务、绿电与绿证',desc:'区分电能量、系统服务和环境权益。',minutes:12,sections:[['辅助服务','调频、备用等服务帮助系统保持安全和运行质量。辅助服务的产品定义、补偿与费用分摊需看适用规则，不能简单套用电能量价格。'],['绿电交易','绿色电力交易涉及电能量及相应环境价值。应核对交割、结算和环境权益对应关系，避免把电能量价格和环境价值重复计算。'],['绿证','绿证承载可再生能源电力的环境属性。绿电交易与单独绿证交易的组织方式、核发和划转安排须依据对应规则核验。']],quiz:{q:'调频服务主要帮助系统实现什么？',options:['频率稳定','改变合同字体','降低所有用户的固定税费'],answer:0,explain:'调频服务响应系统频率变化，维护运行稳定。'}},
 {id:6,stage:2,title:'动手完成一次单节点出清',desc:'调节需求，观察边际机组和出清价怎样变化。',minutes:15,sections:[['给定三个报价','A 机组容量 80 MW，报价 180 元/MWh；B 容量 100 MW，报价 300 元/MWh；C 容量 120 MW，报价 480 元/MWh。计算一个 1 小时时段。'],['需求为 150 MW','先调用 A 的 80 MW，再调用 B 的 70 MW，C 不调用。总电量为 150 MWh，边际价格为 300 元/MWh。'],['需求增至 220 MW','A 调用 80 MW，B 调用 100 MW，C 调用 40 MW。边际价格上升到 480 元/MWh。观察需求越过 180 MW 时的变化。']],quiz:{q:'需求 220 MW 时，C 机组需要出力多少？',options:['40 MW','120 MW','220 MW'],answer:0,explain:'220 − 80 − 100 = 40 MW。'},lab:'clearing'},
 {id:7,stage:2,title:'日前与实时两结算',desc:'把计划电量与实际偏差分别计价。',minutes:15,sections:[['简化的两结算模型','以买电成本为例：成本 = 日前电量 × 日前价格 +（实际电量 − 日前电量）× 实时价格。该公式仅用于理解两结算机制，不代表所有地区的用户结算方式。'],['代入一个例子','日前安排 100 MWh，价格 300 元/MWh；实际用电 110 MWh，实时价格 450 元/MWh。成本 = 30,000 + 4,500 = 34,500 元。'],['负偏差的含义','若实际仅 90 MWh，偏差为 −10 MWh，实时部分为 −4,500 元；教学模型下成本为 25,500 元。负偏差不是计算错误，它反映相反方向的差额结算。']],quiz:{q:'上述 110 MWh 实际用电场景的结算成本是？',options:['33,000 元','49,500 元','34,500 元'],answer:2,explain:'100 × 300 + (110 − 100) × 450 = 34,500 元。'},lab:'settlement'},
 {id:8,stage:2,title:'节点价格与输电阻塞',desc:'理解为什么同一时刻不同地点的价格可能不同。',minutes:15,sections:[['电网有物理边界','便宜电源并不一定能无限量送到所有负荷位置。线路容量与安全约束可能限制功率输送，迫使局部使用更昂贵的电源。'],['节点边际价格','节点电价表示在特定位置增加单位负荷的边际成本。阻塞和网损等因素可导致节点间价差，具体构成取决于市场设计。'],['从简单模型继续深入','实验室的单节点算例是学习起点。学习网络模型还需要节点连接、潮流约束与优化求解，不能直接用单节点结果解释所有现实价格。']],quiz:{q:'为什么同一时间不同地点可能存在价差？',options:['电网输送存在约束','所有机组报价必须相同','电量不能用 MWh 计量'],answer:0,explain:'网络约束等因素会改变各地点增加负荷的边际成本。'}},
 {id:9,stage:3,title:'省级规则的阅读顺序',desc:'按主体、交易、出清、结算、风险五条线阅读。',minutes:12,sections:[['先确认文件身份','记录名称、发布机构、文号、发布日期、生效日、适用范围和修订关系。征求意见稿、政策解读与正式规则不能相互替代。'],['再定位核心章节','先读总则和主体准入，再读交易申报与组织、出清、计量结算、信息披露、风险防控。把每个参数与条款位置对应。'],['形成个人笔记','每个问题用“条款来源—适用主体—计算口径—例外条件”记录。资料库提供官方入口；未完成最新性核验的记录会明确标注。']],quiz:{q:'阅读规则第一步应该是什么？',options:['直接抄一个价格参数','核对版本、效力和适用范围','只看文件页数'],answer:1,explain:'先确定文件身份与适用性，才能正确理解条款。'}},
 {id:10,stage:3,title:'比较省份时比较什么',desc:'建立省级差异表，避免把外省参数直接搬过来。',minutes:15,sections:[['比较维度','可以比较交易周期、报价方式、时间颗粒度、价格形成、限价、合同衔接、结算周期与风险处置机制。每一项都应附条款出处和版本日期。'],['同名不一定同口径','不同规则中的偏差、电量、价格等术语可能对应不同计量口径。比较前先确认定义、单位、主体和时段。'],['用算例验证理解','拿相同的输入分别按两个地区已核实的规则计算，观察差异来自何处。本版实验室是一般原理模型，还未实现逐省精确结算。']],quiz:{q:'跨省比较价格参数时，至少要核对什么？',options:['网页颜色','单位、主体、时段与规则版本','机构徽标尺寸'],answer:1,explain:'参数的语境和口径必须一致或明确说明差异。'}},
 {id:11,stage:3,title:'从交易结果复盘风险',desc:'连接预测误差、合同敞口与结算结果。',minutes:15,sections:[['拆解结果','区分合同覆盖、现货敞口、预测偏差、其他费用和规则约束，再分析各部分贡献。把所有变化归因于均价会丢失关键细节。'],['做情景分析','分别改变负荷、出力和价格，观察结果。使用实验室中的合同或两结算算例，比较同一输入在不同价格下的变化。'],['建立复盘表','记录预期、实际、偏差、原因和改进动作。现实决策应依据真实曲线、完整费用项目和有效规则；教学模型帮助理解机制。']],quiz:{q:'做复盘时，最有帮助的是哪种方法？',options:['只看总电费','分解合同、偏差与价格影响','忽略实际用电变化'],answer:1,explain:'分解驱动因素才能判断风险来源。'},lab:'contract'}
];
